const dismissAlert = document.getElementById('dismiss-alert');
const host = document.getElementById('alert-host');

dismissAlert.addEventListener('nys-close', () => {
  const newAlert = document.createElement('nys-alert');
  newAlert.setAttribute('type', 'success');
  newAlert.setAttribute('heading', 'You dismissed the alert');
  newAlert.setAttribute('text', 'This new alert replaced it.');
  host.appendChild(newAlert);
});
